export const POW_WORKER_JS: string = "(() => {\n  // ../protocol/dist/constants.js\n  var PROTOCOL_VERSION = 1;\n  var CHALLENGE_ID_BYTES = 32;\n  var NONCE_BYTES = 8;\n  var UINT64_MAX = (1n << 64n) - 1n;\n  var MAX_HOST_CONTEXT_BYTES = 255;\n  var MAX_ARTICLE_PATH_BYTES = 255;\n  var MAX_NICKNAME_BYTES = 50;\n  var MAX_BODY_BYTES = 3e3;\n  var MIN_DIFFICULTY = 0;\n  var MAX_DIFFICULTY = 256;\n\n  // ../protocol/dist/errors.js\n  var ProtocolError = class extends Error {\n    constructor(message) {\n      super(message);\n      this.name = \"ProtocolError\";\n    }\n  };\n\n  // ../protocol/dist/utf8.js\n  var encoder = new TextEncoder();\n  var decoder = new TextDecoder(\"utf-8\", { fatal: true });\n  function hasUnpairedSurrogate(s) {\n    for (let i = 0; i < s.length; i++) {\n      const code = s.charCodeAt(i);\n      if (code >= 55296 && code <= 56319) {\n        const next = s.charCodeAt(i + 1);\n        if (!(next >= 56320 && next <= 57343))\n          return true;\n        i++;\n      } else if (code >= 56320 && code <= 57343) {\n        return true;\n      }\n    }\n    return false;\n  }\n  function utf8EncodeStrict(s) {\n    if (hasUnpairedSurrogate(s)) {\n      throw new ProtocolError(\"Invalid UTF-8: input contains an unpaired surrogate\");\n    }\n    return encoder.encode(s);\n  }\n\n  // ../protocol/dist/encoding.js\n  function encodeCanonicalPayload(p) {\n    if (p.version !== PROTOCOL_VERSION) {\n      throw new ProtocolError(`Unsupported protocol version: ${p.version}`);\n    }\n    const host = utf8EncodeStrict(p.hostContext);\n    const path = utf8EncodeStrict(p.articlePath);\n    const nick = utf8EncodeStrict(p.nickname);\n    const body = utf8EncodeStrict(p.body);\n    assertByteLen(\"hostContext\", host.length, MAX_HOST_CONTEXT_BYTES);\n    assertByteLen(\"articlePath\", path.length, MAX_ARTICLE_PATH_BYTES);\n    assertByteLen(\"nickname\", nick.length, MAX_NICKNAME_BYTES);\n    assertByteLen(\"body\", body.length, MAX_BODY_BYTES);\n    if (p.challengeId.length !== CHALLENGE_ID_BYTES) {\n      throw new ProtocolError(`challengeId must be exactly ${CHALLENGE_ID_BYTES} bytes, got ${p.challengeId.length}`);\n    }\n    if (p.nonce < 0n || p.nonce > UINT64_MAX) {\n      throw new ProtocolError(\"nonce out of uint64 range\");\n    }\n    const total = 1 + 2 + host.length + 2 + path.length + 2 + nick.length + 4 + body.length + CHALLENGE_ID_BYTES + NONCE_BYTES;\n    const out = new Uint8Array(total);\n    const view = new DataView(out.buffer);\n    let o = 0;\n    view.setUint8(o, p.version);\n    o += 1;\n    view.setUint16(o, host.length, false);\n    o += 2;\n    out.set(host, o);\n    o += host.length;\n    view.setUint16(o, path.length, false);\n    o += 2;\n    out.set(path, o);\n    o += path.length;\n    view.setUint16(o, nick.length, false);\n    o += 2;\n    out.set(nick, o);\n    o += nick.length;\n    view.setUint32(o, body.length, false);\n    o += 4;\n    out.set(body, o);\n    o += body.length;\n    out.set(p.challengeId, o);\n    o += CHALLENGE_ID_BYTES;\n    view.setBigUint64(o, p.nonce, false);\n    o += NONCE_BYTES;\n    if (o !== total) {\n      throw new ProtocolError(`internal encoding error: wrote ${o} of ${total} bytes`);\n    }\n    return out;\n  }\n  function serializeNonce(nonce) {\n    if (nonce < 0n || nonce > UINT64_MAX) {\n      throw new ProtocolError(\"nonce out of uint64 range\");\n    }\n    if (nonce <= BigInt(Number.MAX_SAFE_INTEGER)) {\n      return Number(nonce);\n    }\n    return nonce.toString(10);\n  }\n  function assertByteLen(field, actual, max) {\n    if (actual > max) {\n      throw new ProtocolError(`${field} exceeds ${max} UTF-8 bytes (got ${actual})`);\n    }\n  }\n\n  // ../protocol/dist/crypto.js\n  var subtle = globalThis.crypto.subtle;\n  async function sha256(data) {\n    const digest = await subtle.digest(\"SHA-256\", data);\n    return new Uint8Array(digest);\n  }\n\n  // ../protocol/dist/base64url.js\n  var ALPHABET = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_\";\n  var LOOKUP = buildLookup();\n  function buildLookup() {\n    const table = new Int16Array(128).fill(-1);\n    for (let i = 0; i < ALPHABET.length; i++) {\n      table[ALPHABET.charCodeAt(i)] = i;\n    }\n    return table;\n  }\n  function base64UrlToBytes(input) {\n    if (input.length === 0)\n      return new Uint8Array(0);\n    if (input.includes(\"=\")) {\n      throw new ProtocolError(\"base64url input must not contain padding\");\n    }\n    if (input.length % 4 === 1) {\n      throw new ProtocolError(\"base64url input has invalid length\");\n    }\n    const out = [];\n    let buffer = 0;\n    let bits = 0;\n    for (let i = 0; i < input.length; i++) {\n      const code = input.charCodeAt(i);\n      const value = code < 128 ? LOOKUP[code] : -1;\n      if (value < 0) {\n        throw new ProtocolError(`invalid base64url character at index ${i}`);\n      }\n      buffer = buffer << 6 | value;\n      bits += 6;\n      if (bits >= 8) {\n        bits -= 8;\n        out.push(buffer >> bits & 255);\n      }\n    }\n    return new Uint8Array(out);\n  }\n\n  // ../protocol/dist/pow.js\n  function leadingZeroBits(hash) {\n    let bits = 0;\n    for (const byte of hash) {\n      if (byte === 0) {\n        bits += 8;\n        continue;\n      }\n      let b = byte;\n      while ((b & 128) === 0) {\n        bits += 1;\n        b = b << 1 & 255;\n      }\n      break;\n    }\n    return bits;\n  }\n  function assertDifficulty(difficulty) {\n    if (!Number.isInteger(difficulty) || difficulty < MIN_DIFFICULTY || difficulty > MAX_DIFFICULTY) {\n      throw new ProtocolError(`difficulty must be an integer in [${MIN_DIFFICULTY}, ${MAX_DIFFICULTY}]`);\n    }\n  }\n  async function verifyPow(canonicalPayload, difficulty) {\n    assertDifficulty(difficulty);\n    const digest = await sha256(canonicalPayload);\n    return leadingZeroBits(digest) >= difficulty;\n  }\n  async function verifyPowFields(payload, difficulty) {\n    return verifyPow(encodeCanonicalPayload(payload), difficulty);\n  }\n  async function mineNonce(base, difficulty, options = {}) {\n    assertDifficulty(difficulty);\n    const start = options.startNonce ?? 0n;\n    const maxAttempts = options.maxAttempts ?? 1n << 32n;\n    if (start < 0n || start > UINT64_MAX) {\n      throw new ProtocolError(\"startNonce out of uint64 range\");\n    }\n    let nonce = start;\n    for (let i = 0n; i < maxAttempts; i++) {\n      if (nonce > UINT64_MAX)\n        break;\n      const payload = encodeCanonicalPayload({ ...base, nonce });\n      const digest = await sha256(payload);\n      if (leadingZeroBits(digest) >= difficulty) {\n        return nonce;\n      }\n      nonce += 1n;\n    }\n    throw new ProtocolError(`mineNonce: no nonce satisfying difficulty ${difficulty} within ${maxAttempts} attempts`);\n  }\n\n  // src/pow-worker.js\n  self.onmessage = async function(event) {\n    var msg = event.data || {};\n    var challenge = msg.challenge;\n    var nickname = msg.nickname;\n    var body = msg.body;\n    try {\n      if (!challenge || typeof challenge.challengeId !== \"string\" || typeof nickname !== \"string\" || typeof body !== \"string\") {\n        throw new Error(\"malformed solve request\");\n      }\n      var base = {\n        version: PROTOCOL_VERSION,\n        hostContext: challenge.hostContext,\n        articlePath: challenge.articlePath,\n        nickname,\n        body,\n        challengeId: base64UrlToBytes(challenge.challengeId)\n      };\n      var nonce = await mineNonce(base, challenge.difficulty);\n      if (!await verifyPowFields({ ...base, nonce }, challenge.difficulty)) {\n        throw new Error(\"internal: mined nonce failed verification\");\n      }\n      self.postMessage({ type: \"nonce\", nonce: serializeNonce(nonce) });\n    } catch (err) {\n      self.postMessage({ type: \"error\", message: err instanceof Error ? err.message : String(err) });\n    }\n  };\n})();\n";

export const ADMIN_HTML: string = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>StaticLayer — Admin</title>\n<style>\n  :root {\n    --accent:#f57d1f; --accent-2:#e85d0a; --ink:#1a1a1a; --muted:#6f6f6f; --line:rgba(0,0,0,.08);\n    --glass:rgba(255,255,255,.66); --danger:#dc2626; --ok:#16a34a;\n    --shadow:0 1px 2px rgba(16,24,40,.04),0 20px 50px -24px rgba(16,24,40,.25);\n  }\n  @media(prefers-color-scheme:dark){ :root {\n    --ink:#f4f4f4; --muted:#9d9d9d; --line:rgba(255,255,255,.08);\n    --glass:rgba(24,24,24,.6); --shadow:0 1px 2px rgba(0,0,0,.4),0 24px 60px -24px rgba(0,0,0,.7);\n  }}\n  * { box-sizing:border-box; }\n  body { margin:0; font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Inter,Roboto,\"Helvetica Neue\",Arial,sans-serif;\n    color:var(--ink); line-height:1.55; min-height:100vh; -webkit-font-smoothing:antialiased;\n    background:\n      radial-gradient(900px 500px at 88% -8%, rgba(245,125,31,.14), transparent 60%),\n      radial-gradient(800px 500px at -8% 12%, rgba(124,92,255,.10), transparent 55%),\n      #f7f7f5; }\n  @media(prefers-color-scheme:dark){ body { background:\n      radial-gradient(900px 500px at 88% -8%, rgba(245,125,31,.12), transparent 60%),\n      radial-gradient(800px 500px at -8% 12%, rgba(124,92,255,.08), transparent 55%),\n      #161616; }}\n  .wrap { max-width:680px; margin:0 auto; padding:48px 20px 80px; }\n  .brand { display:flex; align-items:center; justify-content:center; gap:12px; margin-bottom:26px; }\n  .logo { width:42px; height:42px; border-radius:13px; display:flex; align-items:center; justify-content:center; font-size:20px;\n    background:linear-gradient(135deg,var(--accent),var(--accent-2)); box-shadow:0 10px 26px -10px rgba(245,125,31,.65); }\n  .brand h1 { margin:0; font-size:18px; letter-spacing:-.3px; }\n  .brand span { font-size:12.5px; color:var(--muted); }\n  .glass { backdrop-filter:blur(20px) saturate(1.5); -webkit-backdrop-filter:blur(20px) saturate(1.5);\n    background:var(--glass); border:1px solid var(--line); border-radius:22px; box-shadow:var(--shadow); }\n  .panel { padding:28px; }\n  .panel h2 { margin:0 0 4px; font-size:17px; letter-spacing:-.2px; }\n  .panel .sub { margin:0 0 20px; font-size:13px; color:var(--muted); }\n  label { display:block; font-size:12.5px; font-weight:600; color:var(--muted); margin-bottom:8px; }\n  input[type=password] { width:100%; padding:12px 14px; border:1px solid var(--line); border-radius:12px;\n    background:rgba(255,255,255,.55); color:var(--ink); font:inherit; font-size:14px; outline:none;\n    transition:border-color .15s ease,box-shadow .15s ease; }\n  @media(prefers-color-scheme:dark){ input[type=password]{ background:rgba(255,255,255,.06); } }\n  input[type=password]:focus { border-color:var(--accent); box-shadow:0 0 0 3px rgba(245,125,31,.14); }\n  button { appearance:none; border:0; cursor:pointer; font:inherit; font-weight:600; font-size:13.5px;\n    padding:10px 18px; border-radius:999px; color:#fff; background:linear-gradient(135deg,var(--accent),var(--accent-2));\n    box-shadow:0 6px 16px -6px rgba(245,125,31,.55); transition:transform .12s ease,filter .12s ease,opacity .12s ease; }\n  button:hover { transform:translateY(-1px); filter:brightness(1.05); }\n  button:disabled { opacity:.55; cursor:progress; transform:none; filter:none; }\n  button.ghost { background:transparent; color:var(--muted); border:1px solid var(--line); box-shadow:none; }\n  button.ghost:hover { border-color:var(--line); color:var(--ink); }\n  button.danger { background:transparent; color:var(--danger); border:1px solid color-mix(in srgb,var(--danger) 35%,transparent); box-shadow:none; }\n  button.danger:hover { background:rgba(220,38,38,.06); }\n  .row { display:flex; gap:10px; margin-top:16px; }\n  .status { min-height:1.2em; margin:14px 2px 0; font-size:13px; color:var(--muted); }\n  .status.err { color:var(--danger); }\n  ul { list-style:none; margin:0; padding:0; display:flex; flex-direction:column; gap:12px; }\n  .comment { display:flex; gap:12px; padding:16px; border:1px solid var(--line); border-radius:16px; background:rgba(255,255,255,.5); }\n  @media(prefers-color-scheme:dark){ .comment { background:rgba(255,255,255,.04); } }\n  .avatar { flex:none; width:34px; height:34px; border-radius:10px; display:flex; align-items:center; justify-content:center;\n    color:#fff; font-weight:650; font-size:13px; background:linear-gradient(135deg,var(--accent),var(--accent-2)); }\n  .main { min-width:0; flex:1; }\n  .head { display:flex; align-items:baseline; gap:8px; flex-wrap:wrap; margin-bottom:2px; }\n  .nick { font-weight:600; font-size:13px; }\n  .time { font-size:11.5px; color:var(--muted); font-variant-numeric:tabular-nums; }\n  .body { margin:0 0 10px; font-size:14px; white-space:pre-wrap; overflow-wrap:break-word; }\n  .actions { display:flex; gap:8px; }\n  .actions button { padding:7px 14px; font-size:12.5px; }\n  .empty { padding:26px; text-align:center; color:var(--muted); font-size:14px; border:1px dashed var(--line); border-radius:16px; }\n  .page-chip { display:inline-block; font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace; font-size:11px;\n    color:var(--muted); background:rgba(0,0,0,.04); border:1px solid var(--line); border-radius:999px; padding:2px 9px; }\n  @media(prefers-color-scheme:dark){ .page-chip { background:rgba(255,255,255,.06); } }\n  .pages-list { list-style:none; margin:0; padding:0; display:flex; flex-direction:column; gap:8px; }\n  .page-row { display:flex; align-items:center; gap:10px; padding:11px 14px; border:1px solid var(--line); border-radius:12px; background:rgba(255,255,255,.5); }\n  @media(prefers-color-scheme:dark){ .page-row { background:rgba(255,255,255,.04); } }\n  .page-row .path { font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace; font-size:12.5px; font-weight:600; min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }\n  .page-row .counts { margin-left:auto; display:flex; gap:6px; flex:none; }\n  .count-pill { font-size:11px; font-weight:650; padding:2px 8px; border-radius:999px; }\n  .count-pill.total { color:var(--muted); background:rgba(0,0,0,.05); }\n  .count-pill.pending { color:var(--muted); background:rgba(245,125,31,.14); }\n  .count-pill.approved { color:var(--ok); background:rgba(22,163,74,.12); }\n  @media(prefers-color-scheme:dark){ .count-pill.total { background:rgba(255,255,255,.07); } }\n  .section-gap { height:20px; }\n  footer { margin-top:24px; text-align:center; font-size:12px; color:var(--muted); }\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <div class=\"brand\">\n    <div class=\"logo\">\n      <svg viewBox=\"0 0 64 64\" width=\"26\" height=\"26\" aria-hidden=\"true\"><g fill=\"#fff\"><rect x=\"15\" y=\"39\" width=\"34\" height=\"7\" rx=\"3.5\"/><rect x=\"15\" y=\"30\" width=\"27\" height=\"7\" rx=\"3.5\" opacity=\"0.82\"/><rect x=\"15\" y=\"21\" width=\"20\" height=\"7\" rx=\"3.5\" opacity=\"0.64\"/></g></svg>\n    </div>\n    <div>\n      <h1>StaticLayer</h1>\n      <span>Moderation console</span>\n    </div>\n  </div>\n\n  <main>\n    <section id=\"login-view\" class=\"glass panel\">\n      <h2>Sign in</h2>\n      <p class=\"sub\">Use the admin password bound to this worker.</p>\n      <form id=\"login-form\">\n        <label for=\"password\">Password</label>\n        <input type=\"password\" id=\"password\" autocomplete=\"current-password\" required>\n        <div class=\"row\"><button type=\"submit\">Sign in</button></div>\n      </form>\n      <p id=\"login-status\" class=\"status\"></p>\n    </section>\n\n    <section id=\"admin-view\" class=\"glass panel\" hidden>\n      <h2>Pages with comments</h2>\n      <p class=\"sub\">Every page that received comments on this Worker.</p>\n      <ul id=\"pages-list\" class=\"pages-list\"></ul>\n      <div class=\"section-gap\"></div>\n      <h2>Moderation queue</h2>\n      <p class=\"sub\">Comments awaiting approval.</p>\n      <ul id=\"pending-list\"></ul>\n      <p id=\"list-status\" class=\"status\"></p>\n      <div class=\"section-gap\"></div>\n      <h2>Published comments</h2>\n      <p class=\"sub\">Already public — you can unapprove or delete them.</p>\n      <ul id=\"published-list\"></ul>\n      <p id=\"pub-status\" class=\"status\"></p>\n    </section>\n  </main>\n\n  <footer>StaticLayer · BYOC · open source (MIT)</footer>\n</div>\n<script src=\"/admin.js\"></script>\n</body>\n</html>\n";

export const ADMIN_JS: string = "/**\n * StaticLayer admin UI (external script — CSP script-src 'self' forbids inline\n * scripts, so all logic lives here).\n *\n * The CSRF token is kept in a JS variable in memory ONLY — never in\n * localStorage/sessionStorage/cookies. Comment rendering uses textContent only.\n */\n(function () {\n  'use strict';\n\n  var csrf = null;\n\n  var loginForm = document.getElementById('login-form');\n  var loginStatus = document.getElementById('login-status');\n  var loginView = document.getElementById('login-view');\n  var adminView = document.getElementById('admin-view');\n  var pendingList = document.getElementById('pending-list');\n  var listStatus = document.getElementById('list-status');\n  var pagesList = document.getElementById('pages-list');\n  var publishedList = document.getElementById('published-list');\n  var pubStatus = document.getElementById('pub-status');\n\n  function el(tag, className, text) {\n    var node = document.createElement(tag);\n    if (className) node.className = className;\n    if (text !== undefined) node.textContent = text;\n    return node;\n  }\n\n  function showStatus(node, message, isError) {\n    node.textContent = message;\n    node.classList.toggle('err', !!isError);\n  }\n\n  loginForm.addEventListener('submit', function (event) {\n    event.preventDefault();\n    var password = document.getElementById('password').value;\n    showStatus(loginStatus, '');\n    fetch('/api/admin/login', {\n      method: 'POST',\n      headers: { 'content-type': 'application/json' },\n      body: JSON.stringify({ password: password })\n    })\n      .then(function (res) { return res.json().then(function (data) { return { ok: res.ok, data: data }; }); })\n      .then(function (outcome) {\n        if (outcome.ok && outcome.data.csrf) {\n          csrf = outcome.data.csrf; // in-memory only — never persisted\n          loginView.hidden = true;\n          adminView.hidden = false;\n          loadPages();\n          loadPending();\n          loadPublished();\n        } else {\n          showStatus(loginStatus, 'Incorrect password.', true);\n        }\n      })\n      .catch(function () { showStatus(loginStatus, 'Sign-in failed.', true); });\n  });\n\n  function loadPages() {\n    if (!pagesList) return;\n    fetch('/api/admin/articles', { credentials: 'same-origin' })\n      .then(function (res) { if (!res.ok) throw new Error('request failed'); return res.json(); })\n      .then(function (data) {\n        var articles = Array.isArray(data.articles) ? data.articles : [];\n        pagesList.replaceChildren();\n        if (articles.length === 0) {\n          pagesList.appendChild(el('li', 'empty', 'No comments yet on any page.'));\n          return;\n        }\n        articles.forEach(function (a) {\n          var row = el('li', 'page-row');\n          row.append(el('span', 'path', a.article_path));\n          var counts = el('div', 'counts');\n          counts.append(\n            el('span', 'count-pill total', a.total + ' total'),\n            el('span', 'count-pill pending', a.pending + ' pending'),\n            el('span', 'count-pill approved', a.approved + ' approved')\n          );\n          row.append(counts);\n          pagesList.appendChild(row);\n        });\n      })\n      .catch(function () { /* non-fatal: queue still loads */ });\n  }\n\n  function loadPublished() {\n    if (!publishedList) return;\n    showStatus(pubStatus, 'Loading…');\n    fetch('/api/admin/comments?status=approved', { credentials: 'same-origin' })\n      .then(function (res) { if (!res.ok) throw new Error('request failed'); return res.json(); })\n      .then(function (data) {\n        var comments = Array.isArray(data.comments) ? data.comments : [];\n        publishedList.replaceChildren();\n        if (comments.length === 0) {\n          publishedList.appendChild(el('li', 'empty', 'No published comments yet.'));\n          showStatus(pubStatus, '');\n          return;\n        }\n        comments.forEach(function (c) {\n          var nick = (c.nickname && c.nickname.trim()) || 'Anonymous';\n          var li = el('li', 'comment');\n          var avatar = el('div', 'avatar', nick.charAt(0).toUpperCase());\n          var main = el('div', 'main');\n          var head = el('div', 'head');\n          head.append(el('span', 'nick', nick), el('span', 'time', new Date(c.created_at * 1000).toLocaleString()));\n          if (c.article_path) head.append(el('span', 'page-chip', c.article_path));\n          var body = el('p', 'body', c.body); // textContent only — XSS-safe\n          var actions = el('div', 'actions');\n          var unapproveBtn = el('button', null, 'Unapprove');\n          var deleteBtn = el('button', 'danger', 'Delete');\n          unapproveBtn.addEventListener('click', function () { moderate(c.id, 'unapprove'); });\n          deleteBtn.addEventListener('click', function () { moderate(c.id, 'delete'); });\n          actions.append(unapproveBtn, deleteBtn);\n          main.append(head, body, actions);\n          li.append(avatar, main);\n          publishedList.appendChild(li);\n        });\n        showStatus(pubStatus, '');\n      })\n      .catch(function (err) { showStatus(pubStatus, 'Error: ' + err.message, true); });\n  }\n\n  function loadPending() {\n    showStatus(listStatus, 'Loading…');\n    fetch('/api/admin/comments?status=pending', { credentials: 'same-origin' })\n      .then(function (res) { if (!res.ok) throw new Error('request failed'); return res.json(); })\n      .then(function (data) {\n        var comments = Array.isArray(data.comments) ? data.comments : [];\n        pendingList.replaceChildren();\n        if (comments.length === 0) {\n          pendingList.appendChild(el('li', 'empty', 'No comments awaiting approval. 🎉'));\n          showStatus(listStatus, '');\n          return;\n        }\n        comments.forEach(function (c) {\n          var nick = (c.nickname && c.nickname.trim()) || 'Anonymous';\n          var li = el('li', 'comment');\n          var avatar = el('div', 'avatar', nick.charAt(0).toUpperCase());\n          var main = el('div', 'main');\n          var head = el('div', 'head');\n          head.append(el('span', 'nick', nick), el('span', 'time', new Date(c.created_at * 1000).toLocaleString()));\n          if (c.article_path) head.append(el('span', 'page-chip', c.article_path));\n          var body = el('p', 'body', c.body); // textContent only — XSS-safe\n          var actions = el('div', 'actions');\n          var approveBtn = el('button', null, 'Approve');\n          var deleteBtn = el('button', 'danger', 'Delete');\n          approveBtn.addEventListener('click', function () { moderate(c.id, 'approve'); });\n          deleteBtn.addEventListener('click', function () { moderate(c.id, 'delete'); });\n          actions.append(approveBtn, deleteBtn);\n          main.append(head, body, actions);\n          li.append(avatar, main);\n          pendingList.appendChild(li);\n        });\n        showStatus(listStatus, '');\n      })\n      .catch(function (err) { showStatus(listStatus, 'Error: ' + err.message, true); });\n  }\n\n  function moderate(id, action) {\n    if (!csrf) { showStatus(listStatus, 'Not authenticated', true); return; }\n    var options = {\n      method: action === 'approve' || action === 'unapprove' ? 'PATCH' : 'DELETE',\n      credentials: 'same-origin',\n      headers: { 'X-CSRF-Token': csrf }\n    };\n    if (action === 'approve' || action === 'unapprove') {\n      options.headers['content-type'] = 'application/json';\n      options.body = JSON.stringify({ status: action === 'approve' ? 'approved' : 'pending' });\n    }\n    fetch('/api/admin/comments/' + encodeURIComponent(id), options)\n      .then(function (res) {\n        if (!res.ok) throw new Error('moderation failed (' + res.status + ')');\n        loadPending();\n        loadPublished();\n        loadPages();\n      })\n      .catch(function (err) { showStatus(listStatus, 'Error: ' + err.message, true); });\n  }\n})();\n";
